from collections import deque
D=[(1,0),(-1,0),(0,1),(0,-1)]
def comps(g, color):
 seen=set(); out=[]
 for r,c in zip(*np.where(g==color)):
  if (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); cc=[]
  while q:
   p=q.pop(); cc.append(p)
   for dr,dc in D:
    z=(p[0]+dr,p[1]+dc)
    if 0<=z[0]<g.shape[0] and 0<=z[1]<g.shape[1] and z not in seen and g[z]==color: seen.add(z);q.append(z)
  out.append(cc)
 return out
