def pair_scores(A,B,dt):
 ca=A['cells'];ma=A['marks']; cb={(r+dt[0],c+dt[1]) for r,c in B['cells']};mb={(r+dt[0],c+dt[1]) for r,c in B['marks']}
 if ca&cb:return None
 mm=len(ma&mb); mc=len(ma&cb)+len(mb&ca)
 return mm,mc
for name,A in pieces.items():
 if name=='4': continue
 print('\n',name)
 for other,B in pieces.items():
  if other==name: continue
  cand=[]
  for dr in range(-12,13):
   for dc in range(-12,13):
    s=pair_scores(A,B,(dr,dc))
    if s and sum(s)>0: cand.append((sum(s),*s,dr,dc))
  best=sorted(cand,reverse=True)[:4]
  print(' vs',other, best)

def make_pieces(g):
 P={}
 for color in sorted(set(g.ravel())-{0,2}):
  ccs=comps(g,int(color))
  for ix,cc in enumerate(ccs):
   r0=min(r for r,c in cc); c0=min(c for r,c in cc)
   cells={(r-r0,c-c0) for r,c in cc}; marks=set()
   for r,c in cc:
    for dr,dc in D:
     rr,ccol=r+dr,c+dc
     if 0<=rr<g.shape[0] and 0<=ccol<g.shape[1] and g[rr,ccol]==2: marks.add((rr-r0,ccol-c0))
   name=f'{color}{chr(97+ix) if len(ccs)>1 else ""}'
   P[name]={'color':int(color),'origin':(r0,c0),'cells':cells,'marks':marks}
 return P
